export const CrossSvgIcon = () => (
    <svg width="12" height="12" viewBox="0 0 20 20" fill="#000000">
        <path d="M1 1L19 19" stroke="black" strokeWidth="2" />
        <path d="M1 19L19 1" stroke="black" strokeWidth="2" />
    </svg>
)

export const ColorSvgIcon = () => (
    <svg fill="#000000" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><g id="SVGRepo_bgCarrier" strokeWidth="0"></g><g id="SVGRepo_tracerCarrier" strokeLinecap="round" strokeLinejoin="round"></g><g id="SVGRepo_iconCarrier"><path d="M20 14c-.092.064-2 2.083-2 3.5 0 1.494.949 2.448 2 2.5.906.044 2-.891 2-2.5 0-1.5-1.908-3.436-2-3.5zM9.586 20c.378.378.88.586 1.414.586s1.036-.208 1.414-.586l7-7-.707-.707L11 4.586 8.707 2.293 7.293 3.707 9.586 6 4 11.586c-.378.378-.586.88-.586 1.414s.208 1.036.586 1.414L9.586 20zM11 7.414 16.586 13H5.414L11 7.414z"></path></g></svg>
)

export const PlusSvgIcon = () => (
    <svg className='plus-svg-icon' viewBox="0 0 24 24" width={20}>
        <path fill="currentColor" d="M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z" />
    </svg>
)
